      await db.update(members).set({ isFoundingMember: true, foundingTranche: "patron", foundingNumber: sql`(SELECT MAX(COALESCE(${members.foundingNumber}, ${FREE_FOUNDING_SPOTS})) + 1 FROM ${members})` }).where(and(eq(members.id, member.id), eq(members.isFoundingMember, false)));
