      await db.update(foundingBadgeSessions).set({ status: "verified", signature: args.signature ?? `SIM-FOUNDING-${session.id}` }).where(eq(foundingBadgeSessions.id, session.id));
      ctx.invalidateQueries();
      return { ok: true, foundingNumber: updated.foundingNumber, skrName: updated.skrName ?? undefined };
