      const founderCreditDays = checkout.tier === "founder" ? member.founderCreditDays : 0;
      const expiresAt = new Date(baseTime + (APP_CONFIG.MEMBERSHIP_DAYS + founderCreditDays) * 24 * 60 * 60 * 1000);
      if (founderCreditDays > 0)
        await db.update(members).set({ founderCreditDays: 0 }).where(eq(members.id, member.id));
