      const existing = await db.select().from(reactions).where(and(eq(reactions.memberId, access.member.id), args.threadId ? eq(reactions.threadId, args.threadId) : eq(reactions.replyId, args.replyId ?? 0))).limit(1);
      let authorId = null;
